<script setup>
const props=defineProps({orderId:{type:String,required:true},guestToken:String,totalMoneyCents:{type:String,required:true}})
const busy=ref(false),failure=ref(''),message=ref('')
async function start(){if(busy.value)return;busy.value=true;failure.value='';try{const result=await $fetch('/api/payments/start',{method:'POST',body:{orderId:props.orderId,guestToken:props.guestToken,acceptedTotalCents:props.totalMoneyCents}});if(result.confirmed){message.value=props.totalMoneyCents==='0'?'Pedido confirmado sin cobro requerido.':'Pedido ya confirmado.';await navigateTo(`/pago?pedido=${props.orderId}`)}else await navigateTo(result.url,{external:true})}catch(e){failure.value=e.data?.statusMessage??'No pudimos abrir el pago. Consulta el estado antes de reintentarlo.'}finally{busy.value=false}}
</script>
<template><div class="mt-4"><p class="text-body-s text-ink-2">Solo tarjetas de crédito o débito mediante Stripe. Las existencias se reservarán al iniciar el pago.</p><UiButton class="mt-3" :disabled="busy" @click="start">{{busy?'Preparando pago…':'Ir a pagar con Stripe'}}</UiButton><NuxtLink :to="`/pago?pedido=${orderId}`" class="ml-4 inline-flex min-h-11 items-center text-accent-text underline">Consultar estado</NuxtLink><p v-if="failure" role="alert" class="mt-3 text-crit">{{failure}}</p><p v-if="message" role="status" class="mt-3 text-ok">{{message}}</p></div></template>
